1	module esaxi (/*autoarg*/
2	   // Outputs
3	   wr_access, wr_packet, rd_access, rd_packet, rr_wait, s_axi_arready,
4	   s_axi_awready, s_axi_bid, s_axi_bresp, s_axi_bvalid, s_axi_rid,
5	   s_axi_rdata, s_axi_rlast, s_axi_rresp, s_axi_rvalid, s_axi_wready,
6	   // Inputs
7	   wr_wait, rd_wait, rr_access, rr_packet, s_axi_aclk, s_axi_aresetn,
8	   s_axi_arid, s_axi_araddr, s_axi_arburst, s_axi_arcache,
9	   s_axi_arlock, s_axi_arlen, s_axi_arprot, s_axi_arqos, s_axi_arsize,
10	   s_axi_arvalid, s_axi_awid, s_axi_awaddr, s_axi_awburst,
11	   s_axi_awcache, s_axi_awlock, s_axi_awlen, s_axi_awprot,
12	   s_axi_awqos, s_axi_awsize, s_axi_awvalid, s_axi_bready,
13	   s_axi_rready, s_axi_wid, s_axi_wdata, s_axi_wlast, s_axi_wstrb,
14	   s_axi_wvalid
15	   );
16	   
17	   parameter          S_IDW               = 12;
18	   parameter          PW                  = 104;
19	   parameter [AW-1:0] RETURN_ADDR         = 0;
20	   parameter          AW                  = 32;
21	   parameter          DW                  = 32;
22	
23	`ifdef TARGET_SIM
24	   parameter         TW                  = 16;   //timeout counter width
25	`else
26	   parameter         TW                  = 16;  //timeout counter width
27	`endif
28	 
29	   //#############################
30	   //# Write request
31	   //#############################
32	   output 	   wr_access;   
33	   output [PW-1:0] wr_packet;
34	   input 	   wr_wait;
35	   
36	   //#############################
37	   //# Read request
38	   //#############################
39	   output 	   rd_access;   
40	   output [PW-1:0] rd_packet;
41	   input 	   rd_wait;
42	   
43	   //#############################
44	   //# Read response
45	   //#############################
46	   input 	   rr_access;         
47	   input [PW-1:0]  rr_packet;
48	   output 	   rr_wait;
49	
50	   //#############################
51	   //# AXI Slave Interface
52	   //#############################
53	 
54	   //Clock and reset
55	   input 	  s_axi_aclk;
56	   input 	  s_axi_aresetn;
57	   
58	   //Read address channel
59	   input [S_IDW-1:0] s_axi_arid;    //write address ID
60	   input [31:0]    s_axi_araddr;
61	   input [1:0] 	   s_axi_arburst;
62	   input [3:0] 	   s_axi_arcache;
63	   input  	   s_axi_arlock;
64	   input [7:0] 	   s_axi_arlen;
65	   input [2:0] 	   s_axi_arprot;
66	   input [3:0] 	   s_axi_arqos;
67	   output 	   s_axi_arready;
68	   input [2:0] 	   s_axi_arsize;
69	   input 	   s_axi_arvalid;
70	   
71	   //Write address channel
72	   input [S_IDW-1:0] s_axi_awid;    //write address ID
73	   input [31:0]    s_axi_awaddr;
74	   input [1:0] 	   s_axi_awburst;
75	   input [3:0] 	   s_axi_awcache;
76	   input  	   s_axi_awlock;
77	   input [7:0] 	   s_axi_awlen;
78	   input [2:0] 	   s_axi_awprot;
79	   input [3:0] 	   s_axi_awqos;   
80	   input [2:0] 	   s_axi_awsize;
81	   input 	   s_axi_awvalid;
82	   output 	   s_axi_awready;
83	   
84	   //Buffered write response channel
85	   output [S_IDW-1:0] s_axi_bid;    //write address ID
86	   output [1:0]     s_axi_bresp;
87	   output 	    s_axi_bvalid;
88	   input 	    s_axi_bready;
89	   
90	   //Read channel
91	   output [S_IDW-1:0] s_axi_rid;    //write address ID
92	   output [31:0]      s_axi_rdata;
93	   output 	      s_axi_rlast;   
94	   output [1:0]       s_axi_rresp;
95	   output 	      s_axi_rvalid;
96	   input 	      s_axi_rready;
97	
98	   //Write channel
99	   input [S_IDW-1:0]  s_axi_wid;    //write address ID
100	   input [31:0]       s_axi_wdata;
101	   input 	      s_axi_wlast;   
102	   input [3:0] 	      s_axi_wstrb;
103	   input 	      s_axi_wvalid;
104	   output 	      s_axi_wready;
105	
106	   //###################################################
107	   //#WIRE/REG DECLARATIONS
108	   //###################################################
109	
110	   reg 		      s_axi_awready;
111	   reg 		      s_axi_wready;
112	   reg 		      s_axi_bvalid;
113	   reg [1:0] 	      s_axi_bresp;
114	   reg 		      s_axi_arready;
115	   
116	   reg [31:0] 	      axi_awaddr;  // 32b for epiphany addr
117	   reg [1:0] 	      axi_awburst;
118	   reg [2:0] 	      axi_awsize;
119	   reg [S_IDW-1:0]    axi_bid;     //what to do with this?
120	 
121	   reg [31:0] 	      axi_araddr;
122	   reg [7:0] 	      axi_arlen;
123	   reg [1:0] 	      axi_arburst;
124	   reg [2:0] 	      axi_arsize;
125	   
126	   reg [31:0] 	      s_axi_rdata;
127	   reg [1:0] 	      s_axi_rresp;
128	   reg 		      s_axi_rlast;
129	   reg 		      s_axi_rvalid;
130	   reg [S_IDW-1:0]      s_axi_rid;
131	   
132	   reg 		      read_active;
133	   reg [31:0] 	      read_addr;
134	   reg 		      write_active;
135	   reg 		      b_wait;      // waiting to issue write response (unlikely?)
136	   
137	   reg 		      wr_access;
138	   reg [1:0] 	      wr_datamode;
139	   reg [31:0] 	      wr_dstaddr;
140	   reg [31:0] 	      wr_data;
141	
142	   reg [31:0] 	      wr_data_reg;
143	   reg [31:0] 	      wr_dstaddr_reg;
144	   reg [1:0] 	      wr_datamode_reg;
145	   
146	   reg 		      rd_access;
147	   reg [1:0] 	      rd_datamode;
148	   reg [31:0] 	      rd_dstaddr;
149	   reg [31:0] 	      rd_srcaddr;  //read reaspne address
150	   
151	   reg 		      pre_wr_en;    // delay for data alignment
152	   
153	   reg 		      ractive_reg;  // need leading edge of active for 1st req
154	   reg 		      rnext;
155	        
156	   wire 	      last_wr_beat;
157	   wire 	      last_rd_beat;
158	  
159	   wire [31:0] 	      rr_mux_data;
160	   wire [DW-1:0]      rr_data;
161	   wire [31:0] 	      rr_return_data;
162	   reg [TW-1:0]       timeout_counter;
163	   
164	   //###################################################
165	   //#PACKET TO MESH
166	   //###################################################
167	
168	   //WR
169	   emesh2packet e2p_wr (
170			     // Outputs
171			     .packet_out	(wr_packet[PW-1:0]),
172			     // Inputs
173			     .write_out		(1'b1),
174			     .datamode_out	(wr_datamode[1:0]),
175			     .ctrlmode_out	(5'b0),
176			     .dstaddr_out	(wr_dstaddr[AW-1:0]),
177			     .data_out		(wr_data[DW-1:0]),
178			     .srcaddr_out	(32'b0)//only 32b slave write supported
179			     );
180	
181	   //RD
182	   emesh2packet e2p_rd (
183			     // Outputs
184			     .packet_out	(rd_packet[PW-1:0]),
185			     // Inputs
186			     .write_out		(1'b0),
187			     .datamode_out	(rd_datamode[1:0]),
188			     .ctrlmode_out	(5'b0),
189			     .dstaddr_out	(rd_dstaddr[AW-1:0]),
190			     .data_out		(32'b0),
191			     .srcaddr_out	(rd_srcaddr[AW-1:0])
192			     );   
193	   //RR
194	   packet2emesh p2e_rr (
195				  // Outputs
196				  .write_in		(),
197				  .datamode_in		(),
198				  .ctrlmode_in		(),
199				  .dstaddr_in		(),
200				  .data_in		(rr_data[DW-1:0]),
201				  .srcaddr_in		(),
202				  // Inputs
203				  .packet_in		(rr_packet[PW-1:0])
204				  );
205	
206	   //###################################################
207	   //#WRITE ADDRESS CHANNEL
208	   //###################################################
209	
210	   assign  last_wr_beat = s_axi_wready & s_axi_wvalid & s_axi_wlast;
211	   
212	   // axi_awready is asserted when there is no write transfer in progress
213	
214	   always @(posedge s_axi_aclk ) 
215	     begin
216	      if(~s_axi_aresetn)  
217		begin
218	           s_axi_awready <= 1'b1; //TODO: why not set default as 1?
219	           write_active  <= 1'b0;           
220		end 
221	      else 
222		begin
223	           // we're always ready for an address cycle if we're not doing something else
224	           // note: might make this faster by going ready on last beat instead of after,
225	           // but if we want the very best each channel should be fifo'd.
226	           if( ~s_axi_awready & ~write_active & ~b_wait )
227	             s_axi_awready <= 1'b1;
228	           else if( s_axi_awvalid )
229	             s_axi_awready <= 1'b0;
230		   
231	           // the write cycle is "active" as soon as we capture an address, it
232	           // ends on the last beat.
233	           if( s_axi_awready & s_axi_awvalid )
234	             write_active <= 1'b1;
235	           else if( last_wr_beat )
236	             write_active <= 1'b0;         
237		end // else: !if(~s_axi_aresetn)
238	     end // always @ (posedge s_axi_aclk )
239	        
240	   always @( posedge s_axi_aclk ) 
241	     if (~s_axi_aresetn)  
242	       begin
243	          axi_bid[S_IDW-1:0] <= 'd0;  // capture for write response
244	          axi_awaddr[31:0]   <= 32'd0;
245	          axi_awsize[2:0]    <= 3'd0;
246	          axi_awburst[1:0]   <= 2'd0;         
247	       end 
248	     else 
249	       begin	  
250	          if( s_axi_awready & s_axi_awvalid ) 
251		    begin	     
252		       axi_bid[S_IDW-1:0] <= s_axi_awid[S_IDW-1:0];
253	               axi_awaddr[31:0]   <= s_axi_awaddr[31:0];
254	               axi_awsize[2:0]    <= s_axi_awsize[2:0];  // 0=byte, 1=16b, 2=32b
255	               axi_awburst[1:0]   <= s_axi_awburst[1:0]; // type, 0=fixed, 1=incr, 2=wrap
256	            end 
257		  else if( s_axi_wvalid & s_axi_wready ) 
258	            if( axi_awburst == 2'b01 ) 
259		      begin //incremental burst
260			 //TODOL FIX This, this is not right (double bug canceling!!)
261			 axi_awaddr[31:2] <= axi_awaddr[31:2] + 32'd1;
262			 axi_awaddr[1:0]  <= 2'b0;		 
263		      end 
264	       end // else: !if(~s_axi_aresetn)
265	   
266	   //###################################################
267	   //#WRITE RESPONSE CHANNEL
268	   //###################################################
269	    assign s_axi_bid = axi_bid;
270	   
271	   always @ (posedge s_axi_aclk)
272	     if(~s_axi_aresetn) 
273	       s_axi_wready <= 1'b0;      
274	     else
275	       begin
276		  if( last_wr_beat )
277		    s_axi_wready <= 1'b0;
278		  else if( write_active )
279		    s_axi_wready <= ~wr_wait;
280	       end                             
281	   
282	   always @( posedge s_axi_aclk )
283	     if (~s_axi_aresetn) 
284	       begin
285	          s_axi_bvalid      <= 1'b0;
286	          s_axi_bresp[1:0]  <= 2'b0;
287	          b_wait            <= 1'b0;         
288	       end 
289	     else 
290	       begin         
291	         if( last_wr_beat ) 
292		   begin
293	              s_axi_bvalid      <= 1'b1;
294	              s_axi_bresp[1:0]  <= 2'b0;           // 'okay' response
295	              b_wait            <= ~s_axi_bready;  // note: assumes bready will not drop without valid?            
296	         end 
297		 else if (s_axi_bready & s_axi_bvalid) 
298		   begin	    
299	              s_axi_bvalid <= 1'b0;
300	              b_wait       <= 1'b0;            
301	           end
302	       end // else: !if( s_axi_aresetn == 1'b0 )
303	
304	   //###################################################
305	   //#READ REQUEST CHANNEL
306	   //###################################################  
307	
308	   //No
309	   assign  last_rd_beat = s_axi_rvalid & s_axi_rlast & s_axi_rready;
310	
311	   always @( posedge s_axi_aclk ) 
312	     if (~s_axi_aresetn) 
313	       begin	  
314	         s_axi_arready <= 1'b0;
315	         read_active   <= 1'b0;         
316	       end 
317	     else 
318	       begin    
319		  //arready
320	          if( ~s_axi_arready & ~read_active )
321	            s_axi_arready <= 1'b1;
322	          else if( s_axi_arvalid )
323	            s_axi_arready <= 1'b0;
324	
325		  //read_active
326	          if( s_axi_arready & s_axi_arvalid )
327	            read_active <= 1'b1;
328	          else if( last_rd_beat )
329	            read_active <= 1'b0;         
330	       end // else: !if( s_axi_aresetn == 1'b0 )
331	   
332	   //Read address channel state machine
333	   always @( posedge s_axi_aclk ) 
334	      if (~s_axi_aresetn) 
335		begin
336	           axi_araddr[31:0]   <= 0;
337	           axi_arlen          <= 8'd0;
338	           axi_arburst        <= 2'd0;
339	           axi_arsize[2:0]    <= 3'b0;
340	           s_axi_rlast        <= 1'b0;
341	           s_axi_rid[S_IDW-1:0] <= 'd0;         
342		end
343	      else 
344		begin         
345	         if( s_axi_arready & s_axi_arvalid ) 
346		   begin	      
347	              axi_araddr[31:0]   <= s_axi_araddr[31:0]; //NOTE: upper 2 bits get chopped by Zynq
348	              axi_arlen[7:0]     <= s_axi_arlen[7:0];
349	              axi_arburst        <= s_axi_arburst;
350	              axi_arsize         <= s_axi_arsize;
351	              s_axi_rlast        <= ~(|s_axi_arlen[7:0]);
352	              s_axi_rid[S_IDW-1:0] <= s_axi_arid[S_IDW-1:0];              
353	         end 
354		 else if( s_axi_rvalid & s_axi_rready) 
355		   begin	      
356	              axi_arlen[7:0] <= axi_arlen[7:0] - 1;
357	              if(axi_arlen[7:0] == 8'd1)
358			s_axi_rlast <= 1'b1;              
359	              if( s_axi_arburst == 2'b01) 
360			begin //incremental burst
361			   axi_araddr[31:2] <= axi_araddr[31:2] + 1;
362			   axi_araddr[1:0]  <= 2'b0;   
363			end
364	           end // if ( s_axi_rvalid & s_axi_rready)
365		end // else: !if( s_axi_aresetn == 1'b0 )
366	   
367	
368	   //###################################################
369	   //#WRITE REQUEST
370	   //###################################################  
371	   
372	   always @( posedge s_axi_aclk ) 
373	     if (~s_axi_aresetn) 
374	       begin
375	          wr_data_reg[31:0]     <= 32'd0;	  
376	          wr_dstaddr_reg[31:0]  <= 32'd0;	 
377	          wr_datamode_reg[1:0]  <= 2'd0;
378	          wr_access             <= 1'b0;
379	          pre_wr_en               <= 1'b0;
380	       end 
381	     else 
382	       begin
383		  pre_wr_en                 <= s_axi_wready & s_axi_wvalid;
384	          wr_access               <= pre_wr_en;
385		  wr_datamode_reg[1:0]    <= axi_awsize[1:0];	
386	          wr_dstaddr_reg[31:2]    <= axi_awaddr[31:2]; //set lsbs of address based on write strobes	 
387		  //What is up with this logic??
388		  if(s_axi_wstrb[0])//| (axi_awsize[1:0]==2'b10)32-bits
389		    begin
390		       wr_data_reg[31:0]   <= s_axi_wdata[31:0];
391		       wr_dstaddr_reg[1:0] <= 2'd0;
392		    end
393		  else if(s_axi_wstrb[1])
394		    begin
395		       wr_data_reg[31:0]   <= {8'd0, s_axi_wdata[31:8]};
396		       wr_dstaddr_reg[1:0] <= 2'd1;
397		    end
398		  else if(s_axi_wstrb[2])
399		    begin
400		       wr_data_reg[31:0]   <= {16'd0, s_axi_wdata[31:16]};
401		       wr_dstaddr_reg[1:0] <= 2'd2;
402		    end
403		  else
404		    begin
405		       wr_data_reg[31:0]   <= {24'd0, s_axi_wdata[31:24]};
406		       wr_dstaddr_reg[1:0] <= 2'd3;
407		    end
408	       end // else: !if(~s_axi_aresetn)
409	
410	   //Pipeline stage!
411	   always @( posedge s_axi_aclk )     
412	     begin
413	        wr_data[31:0]     <= wr_data_reg[31:0];	  
414	        wr_dstaddr[31:0]  <= wr_dstaddr_reg[31:0];	  
415	        wr_datamode[1:0]  <= wr_datamode_reg[1:0];	  
416	     end
417	   
418	   //###################################################
419	   //#READ REQUEST (DATA CHANNEL)
420	   //###################################################  
421	   // -- reads are performed by sending a read
422	   // -- request out the tx port and waiting for
423	   // -- data to come back through the rx read response port.
424	   // --
425	   // -- because elink reads are not generally 
426	   // -- returned in order, we will only allow
427	   // -- one at a time.
428	   //Need to look at rd_wait signal
429	   
430	   always @( posedge s_axi_aclk )
431	     if (~s_axi_aresetn) 
432	       begin
433		  rd_access         <= 1'b0;      
434		  rd_datamode[1:0]  <= 2'd0;
435		  rd_dstaddr[31:0]  <= 32'd0;
436		  rd_srcaddr[31:0]  <= 32'd0;	 
437	          ractive_reg       <= 1'b0;
438	          rnext             <= 1'b0;          
439	      end 
440	     else
441	       begin
442	          ractive_reg       <= read_active;
443	          rnext             <= s_axi_rvalid & s_axi_rready & ~s_axi_rlast;    
444	          rd_access         <= ( ~ractive_reg & read_active ) | rnext;       
445		  rd_datamode[1:0]  <= axi_arsize[1:0];
446		  rd_dstaddr[31:0]  <= axi_araddr[31:0];
447		  rd_srcaddr[31:0]  <= RETURN_ADDR;
448		  //TODO: use arid+srcaddr for out of order ?
449	       end
450	
451	   //###################################################
452	   //#READ RESPONSE (DATA CHANNEL)
453	   //###################################################  
454	   //Read response AXI state machine
455	   //Only one outstanding read
456	
457	   assign rr_wait = 1'b0;
458	
459	
460	   assign rr_return_access     = rr_access | rr_timeout_access;
461	   assign rr_return_data[31:0] = rr_timeout_access ? 32'hDEADBEEF :
462					                         rr_data[31:0];
463	   
464	   always @( posedge s_axi_aclk ) 
465	      if (!s_axi_aresetn) 
466		begin
467	           s_axi_rvalid       <= 1'b0;
468	           s_axi_rdata[31:0]  <= 32'd0;
469	           s_axi_rresp        <= 2'd0;	   
470		end 
471	      else 
472		begin
473	         if( rr_return_access ) 
474		   begin
475	              s_axi_rvalid <= 1'b1;
476	              s_axi_rresp  <= rr_timeout_access ? 2'b10 : 2'b00;
477	            case( axi_arsize[1:0] )
478	              2'b00:   s_axi_rdata[31:0] <= {4{rr_return_data[7:0]}};  //8-bit
479	              2'b01:   s_axi_rdata[31:0] <= {2{rr_return_data[15:0]}}; //16-bit
480	              default: s_axi_rdata[31:0] <= rr_return_data[31:0];      //32-bit
481	            endcase // case ( axi_arsize[1:0] )
482	           end 
483		 else if( s_axi_rready ) 
484	           s_axi_rvalid <= 1'b0;
485		end // else: !if( s_axi_aresetn == 1'b0 )
486	
487	   //###################################################
488	   //#TIMEOUT CIRCUIT
489	   //###################################################  
490	
491	   reg [1:0] timeout_state;     
492	`define TIMEOUT_IDLE    2'b00
493	`define TIMEOUT_ARMED   2'b01
494	`define TIMEOUT_EXPIRED 2'b10
495	  
496	   always @ (posedge s_axi_aclk)
497	     if(!s_axi_aresetn)
498	       timeout_state[1:0] <= `TIMEOUT_IDLE;
499	     else
500	       case(timeout_state[1:0])
501		 `TIMEOUT_IDLE    : timeout_state[1:0] <= (s_axi_arvalid & s_axi_arready ) ? `TIMEOUT_ARMED : 
502							                                     `TIMEOUT_IDLE;
503		 `TIMEOUT_ARMED   : timeout_state[1:0] <=  rr_access     ? `TIMEOUT_IDLE    :
504							   counter_expired ? `TIMEOUT_EXPIRED : 
505							                     `TIMEOUT_ARMED;
506		 `TIMEOUT_EXPIRED : timeout_state[1:0] <= `TIMEOUT_IDLE;	 
507		 default : timeout_state[1:0]          <= `TIMEOUT_IDLE;
508	       endcase // case (timeout_state[1:0])
509	   	   
510	   //release bus after 64K clock cycles (seems reasonable?)   
511	   always @ (posedge s_axi_aclk)
512	     if(timeout_state[1:0]==`TIMEOUT_IDLE)
513	       timeout_counter[TW-1:0] <= {(TW){1'b1}};   
514	     else if (timeout_state[1:0]==`TIMEOUT_ARMED)  //decrement while counter > 0
515	       timeout_counter[TW-1:0] <= timeout_counter[TW-1:0] - 1'b1;
516	
517	   assign counter_expired     = ~(|timeout_counter[TW-1:0]);
518	   assign rr_timeout_access = (timeout_state[1:0]==`TIMEOUT_EXPIRED);
519	        
520	endmodule // esaxi
521	
522	
